const errs = rows.filter(r => r.status >= 500);
print('total 5xx:', errs.length);
print('5xx by version:', JSON.stringify(errs.reduce((a,r)=>{a[r.version]=(a[r.version]||0)+1;return a;},{})));
print('canary 5xx rows:', JSON.stringify(errs.filter(r=>r.version==='1.1').map(r=>({t:+r.t.toFixed(1), path:r.path, status:r.status, ms:r.ms}))));
const cc = canary.filter(r=>r.path==='/checkout');
const sc = stable.filter(r=>r.path==='/checkout');
print('checkout canary n=', cc.length, '5xx=', cc.filter(r=>r.status>=500).length);
print('checkout stable n=', sc.length, '5xx=', sc.filter(r=>r.status>=500).length);
print('canary checkout p50/p95/p99:', pct(cc.map(r=>r.ms),50), pct(cc.map(r=>r.ms),95), pct(cc.map(r=>r.ms),99));
print('stable checkout p50/p95/p99:', pct(sc.map(r=>r.ms),50), pct(sc.map(r=>r.ms),95), pct(sc.map(r=>r.ms),99));
const wins = [0,30,60,90].map(w=>{const c=canary.filter(r=>r.t>=w&&r.t<w+30); return w+'-'+(w+30)+'s canary5xx='+c.filter(r=>r.status>=500).length;});
print(wins.join(' | '));

const ms = a => a.map(r => r.ms);
print('pct arg check -> canary p95 as 95:', pct(ms(canary), 95), '| as 0.95:', pct(ms(canary), 0.95));
print('overall p95 canary:', pct(ms(canary), 95), 'stable:', pct(ms(stable), 95));
const cE = canary.filter(r => r.status >= 500).length;
const sE = stable.filter(r => r.status >= 500).length;
print('overall err% canary:', (cE / canary.length * 100).toFixed(2), 'stable:', (sE / stable.length * 100).toFixed(2));
const cco = canary.filter(r => r.path === '/checkout');
const sco = stable.filter(r => r.path === '/checkout');
print('checkout err% canary:', (cco.filter(r => r.status >= 500).length / cco.length * 100).toFixed(2), 'stable:', (sco.filter(r => r.status >= 500).length / sco.length * 100).toFixed(2));
print('checkout p95 canary:', pct(ms(cco), 95), 'stable:', pct(ms(sco), 95));
print('non-checkout canary 5xx:', canary.filter(r => r.status >= 500 && r.path !== '/checkout').length);
const w = n => canary.filter(r => r.t >= n && r.t < n + 30 && r.status >= 500).length;
print('canary 5xx per 30s window:', [0, 30, 60, 90].map(w).join(','));
print('windows with >=1 canary 5xx:', [0, 30, 60, 90].filter(n => w(n) > 0).length, 'of 4');

