{
  "decision": "ROLLBACK",
  "why": "All 10 5xx responses in the 120 s test came from the canary (version 1.1); stable (version 1.0) served zero 5xx. Every canary 5xx was on /checkout: canary /checkout had 483 requests with 10 5xx (2.07%) while stable /checkout had 1455 requests with 0 5xx (0.00%), and the canary produced no 5xx on any other path. The canary 5xx were spread across all four 30 s windows (1,3,3,3 - 4 of 4 windows affected), so this is not a one-off startup blip. Latency is not the problem: canary overall p95 is 96 ms. Judgement: a sustained, canary-only error on the checkout path is a customer-visible, revenue-critical regression, and ~2% of canary checkouts failing at 25% traffic would become ~2% of all checkouts at 100%; a few minutes of release delay is much cheaper, so roll back and fix the checkout path before re-trying.",
  "claims": [
    {
      "claim": "All 10 5xx responses in the test came from the canary (version 1.1); stable (version 1.0) served zero 5xx.",
      "query": "const c5 = canary.filter(r => r.status >= 500).length; const s5 = stable.filter(r => r.status >= 500).length; print('canary 5xx: ' + c5 + ' stable 5xx: ' + s5);",
      "expect": "canary 5xx: 10 stable 5xx: 0"
    },
    {
      "claim": "Every canary 5xx was on /checkout: canary /checkout 483 requests / 10 5xx / 2.07%, stable /checkout 1455 requests / 0 5xx / 0.00%, and zero canary 5xx on any non-checkout path.",
      "query": "const cc = canary.filter(r => r.path === '/checkout'); const sc = stable.filter(r => r.path === '/checkout'); const ce = cc.filter(r => r.status >= 500).length; const se = sc.filter(r => r.status >= 500).length; const other = canary.filter(r => r.path !== '/checkout' && r.status >= 500).length; print('checkout canary n=' + cc.length + ' 5xx=' + ce + ' err%=' + (100 * ce / cc.length).toFixed(2) + ' | checkout stable n=' + sc.length + ' 5xx=' + se + ' err%=' + (100 * se / sc.length).toFixed(2) + ' | canary non-checkout 5xx=' + other);",
      "expect": "checkout canary n=483 5xx=10 err%=2.07 | checkout stable n=1455 5xx=0 err%=0.00 | canary non-checkout 5xx=0"
    },
    {
      "claim": "Canary 5xx occurred in all four 30 s windows (1,3,3,3), so the failure is sustained rather than a startup blip.",
      "query": "const w = [0,1,2,3].map(i => canary.filter(r => r.status >= 500 && r.t >= i * 30 && r.t < (i + 1) * 30).length); print('canary 5xx per 30s window: ' + w.join(',') + ' | windows with >=1: ' + w.filter(x => x > 0).length + ' of 4');",
      "expect": "canary 5xx per 30s window: 1,3,3,3 | windows with >=1: 4 of 4"
    },
    {
      "claim": "Canary overall p95 latency is 96 ms, i.e. latency is not degraded and the failure signal is errors.",
      "query": "print('canary p95: ' + pct(canary.map(r => r.ms), 0.95) + ' | stable p95: ' + pct(stable.map(r => r.ms), 0.95));",
      "expect": "canary p95: 96"
    }
  ]
}
